# n8n Code node (Python) — format input to Slack "table" blocks
# Expects items[0]["json"] to contain your structure.
# Produces one output item with {"blocks": [...]}

import re

def rt_cell(text: str, bold: bool = False) -> dict:
    text_el = {"type": "text", "text": text}
    if bold:
        text_el["style"] = {"bold": True}
    return {
        "type": "rich_text",
        "elements": [
            {
                "type": "rich_text_section",
                "elements": [text_el],
            }
        ],
    }

UID_RE = re.compile(r"\bU[A-Z0-9]+\b")

# ---- read input ----
payload = items[0].get("json", items[0])

# Invert channel_users: {"Name": "UID"} -> {"UID": "Name"}
uid_to_name = {}
try:
    cu = _('Code in JavaScript1').first().json.channel_users
    uid_to_name = {v: k for k, v in cu.items() if isinstance(v, str)}
except Exception:
    uid_to_name = {}

def mentionify(raw: str) -> str:
    """
    Replace any Slack UID in 'raw' with the real name using uid_to_name.
    Examples:
      'SM::SM U024035KS81' -> 'SM::SM Florian Pfab'
      'AV::S::HB ' -> '—'
      'SM::SM ' -> 'SM::SM'  (no UID present)
    Unknown UIDs are left as-is.
    """
    if not raw or not raw.strip():
        return "—"

    s = raw.strip()
    def repl(m):
        uid = m.group(0)
        return uid_to_name.get(uid, uid)

    # Replace all UID tokens with names
    replaced = UID_RE.sub(repl, s).strip()

    # Collapse leftover double spaces; return em dash if nothing meaningful
    cleaned = " ".join(replaced.split())
    return cleaned if cleaned else "—"


# Your structure is a list with one object containing "data" and "channel_users".
# We only need the first "data" inner list for rows.
data_groups = payload.get("data")
# Build table rows
rows = []
headers = ["Day", "FZ", "HB"]
rows.append([rt_cell(h, bold=True) for h in headers])

for entry in data_groups:
    day = (entry.get("day") or "").strip() or "—"
    fz = mentionify(entry.get("group_fz", ""))
    hb = mentionify(entry.get("group_hb", ""))
    rows.append([rt_cell(day), rt_cell(fz), rt_cell(hb)])

blocks = [{"type": "table", "rows": rows}]

return [{"json": {"blocks": blocks}}]

