// n8n Function node
// Input: Slack members (z. B. aus users.list oder conversations.members + users.info)
// Output: ein Item { json: { channel_users: { "Real Name": "UXXXX", ... } } }

function extractMembers(inputItems) {
  // Akzeptiert entweder ein Item mit .members:Array oder mehrere Items je Member
  let members = [];
  for (const it of inputItems) {
    const j = it.json ?? {};
    if (Array.isArray(j.members)) {
      members = j.members;
      break;
    }
  }
  if (members.length === 0) {
    // Fallback: jedes Item ist ein Member
    members = inputItems.map(it => it.json).filter(m => m && (m.id || (m.user && m.user.id)));
  }
  return members;
}

function cleanRealName(name) {
  if (!name) return "";
  return String(name).replace(/\s+/g, " ").trim();
}

const members = extractMembers(items);

const dict = {};            // "Real Name" -> "UXXXX"
const ownerForKey = {};     // "Real Name" -> "UXXXX"
const collisions = new Set();

for (const m of members) {
  const id = m.id || (m.user && m.user.id);
  const profile = m.profile || {};
  // Bevorzugt den echten Real Name; fällt auf normalized zurück
  const realNameRaw = profile.real_name ?? profile.real_name_normalized ?? "";
  const realName = cleanRealName(realNameRaw);
  if (!id || !realName) continue;

  if (ownerForKey[realName] && ownerForKey[realName] !== id) {
    // Kollision: mehrere User mit gleichem Real Name -> Key entfernen
    collisions.add(realName);
    delete dict[realName];
  } else if (!ownerForKey[realName]) {
    ownerForKey[realName] = id;
    dict[realName] = id;
  }
  // Gleicher User unter gleichem Namen: nichts zu tun
}

// Sicherheit: Kollisionen entfernen
for (const k of collisions) delete dict[k];

// Ausgabe: ein Item mit channel_users = { "Real Name": "UXXXX" }
return {'channel_users': dict};
